import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p63_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias_opt,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv2d_forward", &conv2d_forward, "Tiled direct conv2d forward",
          py::arg("input"), py::arg("weight"), py::arg("bias"),
          py::arg("stride_h"), py::arg("stride_w"),
          py::arg("pad_h"), py::arg("pad_w"),
          py::arg("dil_h"), py::arg("dil_w"),
          py::arg("groups"));
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_W 16
#define TILE_H 16

// Direct conv2d kernel with shared memory input tiling
// Grid: (N, ceil(OC/OC_TILE), ceil(H_out/TILE_H), ceil(W_out/TILE_W))
// Block: (TILE_W, TILE_H)
// OC_TILE output channels computed per block (sequential in thread)
#define OC_TILE 4

__global__ void conv2d_tiled_kernel(
    const float* __restrict__ input,   // [N, IC, H, W]
    const float* __restrict__ weight,  // [OC, IC/groups, kH, kW]
    const float* __restrict__ bias,    // [OC] or nullptr
    float* __restrict__ output,        // [N, OC, H_out, W_out]
    int N, int IC, int OC,
    int H, int W,
    int H_out, int W_out,
    int kH, int kW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups
) {
    // Each block covers TILE_H x TILE_W output pixels, OC_TILE output channels
    const int tx = threadIdx.x;  // 0..TILE_W-1
    const int ty = threadIdx.y;  // 0..TILE_H-1

    const int tile_x = blockIdx.x;   // W tile index
    const int tile_y = blockIdx.y;   // H tile index
    const int oc_block = blockIdx.z % ((OC + OC_TILE - 1) / OC_TILE);  // OC tile index
    const int n = blockIdx.z / ((OC + OC_TILE - 1) / OC_TILE);          // batch index

    const int out_x = tile_x * TILE_W + tx;
    const int out_y = tile_y * TILE_H + ty;

    const int oc_start = oc_block * OC_TILE;

    // shared memory for input halo tile
    // tile covers: out_y*stride - pad .. (out_y+TILE_H-1)*stride - pad + (kH-1)*dil
    // halo size: TILE_H*stride_h + (kH-1)*dil_h
    const int smem_h = TILE_H * stride_h + (kH - 1) * dil_h;
    const int smem_w = TILE_W * stride_w + (kW - 1) * dil_w;

    // We load one input channel at a time to keep shared memory small
    // smem_h * smem_w <= (16*1 + 2) * (16*1 + 2) = 18*18 = 324 floats = 1296 bytes per channel
    // We use dynamic shared memory declared as extern
    extern __shared__ float smem[];
    // layout: smem[smem_h * smem_w]  (one IC slice at a time)

    float acc[OC_TILE];
    #pragma unroll
    for (int i = 0; i < OC_TILE; i++) acc[i] = 0.0f;

    const int IC_per_group = IC / groups;
    const int OC_per_group = OC / groups;
    const int group = oc_start / OC_per_group;  // which group the oc_start belongs to
    const int ic_start = group * IC_per_group;
    const int ic_end   = ic_start + IC_per_group;

    // Base input coordinates for this tile
    const int in_y0 = tile_y * TILE_H * stride_h - pad_h;
    const int in_x0 = tile_x * TILE_W * stride_w - pad_w;

    const int threads = TILE_H * TILE_W;  // = 256
    const int tid = ty * TILE_W + tx;
    const int smem_size = smem_h * smem_w;

    for (int ic = ic_start; ic < ic_end; ic++) {
        // Load input tile for this (n, ic) slice into shared memory
        const float* inp_ptr = input + ((n * IC + ic) * H) * W;
        for (int idx = tid; idx < smem_size; idx += threads) {
            int sy = idx / smem_w;
            int sx = idx % smem_w;
            int iy = in_y0 + sy;
            int ix = in_x0 + sx;
            if (iy >= 0 && iy < H && ix >= 0 && ix < W) {
                smem[idx] = inp_ptr[iy * W + ix];
            } else {
                smem[idx] = 0.0f;
            }
        }
        __syncthreads();

        // Accumulate over kernel window
        if (out_y < H_out && out_x < W_out) {
            // smem offset for this thread's output pixel
            // input coordinate = out_y*stride + ky*dil - pad = in_y0 + ty*stride_h + ky*dil_h
            // smem_y = ty*stride_h + ky*dil_h
            const int ic_local = ic - ic_start;  // weight index offset
            #pragma unroll
            for (int ky = 0; ky < kH; ky++) {
                #pragma unroll
                for (int kx = 0; kx < kW; kx++) {
                    int sy = ty * stride_h + ky * dil_h;
                    int sx = tx * stride_w + kx * dil_w;
                    float inp_val = smem[sy * smem_w + sx];
                    #pragma unroll
                    for (int i = 0; i < OC_TILE; i++) {
                        int oc = oc_start + i;
                        if (oc < OC) {
                            // weight: [OC, IC_per_group, kH, kW]
                            float w = __ldg(&weight[((oc * IC_per_group + ic_local) * kH + ky) * kW + kx]);
                            acc[i] += inp_val * w;
                        }
                    }
                }
            }
        }
        __syncthreads();
    }

    // Write output
    if (out_y < H_out && out_x < W_out) {
        #pragma unroll
        for (int i = 0; i < OC_TILE; i++) {
            int oc = oc_start + i;
            if (oc < OC) {
                float val = acc[i];
                if (bias != nullptr) val += __ldg(&bias[oc]);
                output[((n * OC + oc) * H_out + out_y) * W_out + out_x] = val;
            }
        }
    }
}

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias_opt,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups
) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    int N  = input.size(0);
    int IC = input.size(1);
    int H  = input.size(2);
    int W  = input.size(3);
    int OC = weight.size(0);
    int kH = weight.size(2);
    int kW = weight.size(3);

    int H_out = (H + 2 * pad_h - dil_h * (kH - 1) - 1) / stride_h + 1;
    int W_out = (W + 2 * pad_w - dil_w * (kW - 1) - 1) / stride_w + 1;

    auto output = torch::empty({N, OC, H_out, W_out}, input.options());

    const float* bias_ptr = nullptr;
    if (bias_opt.has_value() && bias_opt.value().defined()) {
        TORCH_CHECK(bias_opt.value().is_contiguous());
        bias_ptr = bias_opt.value().data_ptr<float>();
    }

    int oc_tiles = (OC + OC_TILE - 1) / OC_TILE;
    int w_tiles  = (W_out + TILE_W - 1) / TILE_W;
    int h_tiles  = (H_out + TILE_H - 1) / TILE_H;

    dim3 block(TILE_W, TILE_H);
    dim3 grid(w_tiles, h_tiles, N * oc_tiles);

    int smem_h = TILE_H * stride_h + (kH - 1) * dil_h;
    int smem_w = TILE_W * stride_w + (kW - 1) * dil_w;
    size_t smem_bytes = smem_h * smem_w * sizeof(float);

    conv2d_tiled_kernel<<<grid, block, smem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, IC, OC,
        H, W,
        H_out, W_out,
        kH, kW,
        stride_h, stride_w,
        pad_h, pad_w,
        dil_h, dil_w,
        groups
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a standard 2D convolution operation with a square input and square kernel.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (int): Size of the square convolution kernel.
            stride (int, optional): Stride of the convolution. Defaults to 1.
            padding (int, optional): Padding applied to the input. Defaults to 0.
            dilation (int, optional): Spacing between kernel elements. Defaults to 1.
            groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv2d = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        ext = _stark_get_extension()
        stride = self.conv2d.stride
        padding = self.conv2d.padding
        dilation = self.conv2d.dilation
        groups = self.conv2d.groups
        weight = self.conv2d.weight
        bias = self.conv2d.bias
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return ext.conv2d_forward(
            x.contiguous(),
            weight.contiguous(),
            bias,
            stride[0], stride[1],
            padding[0], padding[1],
            dilation[0], dilation[1],
            groups
        )
        # <<<END_IMPROVE>>>

