#define TILE_H 16

// Direct conv2d kernel with shared memory input tiling
// Grid: (N, ceil(OC/OC_TILE), ceil(H_out/TILE_H), ceil(W_out/TILE_W))
// Block: (TILE_W, TILE_H)
// OC_TILE output channels computed per block (sequential in thread)
#define OC_TILE 4

__global__ void conv2d_tiled_kernel(
    const float* __restrict__ input,   // [N, IC, H, W]
    const float* __restrict__ weight,  // [OC, IC/groups, kH, kW]
    const float* __restrict__ bias,    // [OC] or nullptr
    float* __restrict__ output,        // [N, OC, H_out, W_out]
    int N, int IC, int OC,
    int H, int W,
    int H_out, int W_out,
    int kH, int kW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups
) {
    // Each block covers TILE_H x TILE_W output pixels, OC_TILE output channels
    const int tx = threadIdx.x;  // 0..TILE_W-1
    const int ty = threadIdx.y;  // 0..TILE_H-1

    const int tile_x = blockIdx.x;   // W tile index
    const int tile_y = blockIdx.y;   // H tile index
    const int oc_block = blockIdx.z % ((OC + OC_TILE - 1) / OC_TILE);  // OC tile index
    const int n = blockIdx.z / ((OC + OC_TILE - 1) / OC_TILE);          // batch index

    const int out_x = tile_x * TILE_W + tx;
    const int out_y = tile_y * TILE_H + ty;

    const int oc_start = oc_block * OC_TILE;

    // shared memory for input halo tile
    // tile covers: out_y*stride - pad .. (out_y+TILE_H-1)*stride - pad + (kH-1)*dil
    // halo size: TILE_H*stride_h + (kH-1)*dil_h
    const int smem_h = TILE_H * stride_h + (kH - 1) * dil_h;
    const int smem_w = TILE_W * stride_w + (kW - 1) * dil_w;

    // We load one input channel at a time to keep shared memory small
    // smem_h * smem_w <= (16*1 + 2) * (16*1 + 2) = 18*18 = 324 floats = 1296 bytes per channel
    // We use dynamic shared memory declared as extern
    extern __shared__ float smem[];
    // layout: smem[smem_h * smem_w]  (one IC slice at a time)

    float acc[OC_TILE];
    #pragma unroll
    for (int i = 0; i < OC_TILE; i++) acc[i] = 0.0f;

    const int IC_per_group = IC / groups;
    const int OC_per_group = OC / groups;
    const int group = oc_start / OC_per_group;  // which group the oc_start belongs to
    const int ic_start = group * IC_per_group;
    const int ic_end   = ic_start + IC_per_group;

    // Base input coordinates for this tile
    const int in_y0 = tile_y * TILE_H * stride_h - pad_h;
    const int in_x0 = tile_x * TILE_W * stride_w - pad_w;

    const int threads = TILE_H * TILE_W;  // = 256
    const int tid = ty * TILE_W + tx;
    const int smem_size = smem_h * smem_w;

    for (int ic = ic_start; ic < ic_end; ic++) {
        // Load input tile for this (n, ic) slice into shared memory
        const float* inp_ptr = input + ((n * IC + ic) * H) * W;
        for (int idx = tid; idx < smem_size; idx += threads) {
            int sy = idx / smem_w;
            int sx = idx % smem_w;
            int iy = in_y0 + sy;
            int ix = in_x0 + sx;
            if (iy >= 0 && iy < H && ix >= 0 && ix < W) {
                smem[idx] = inp_ptr[iy * W + ix];
            } else {
                smem[idx] = 0.0f;
            }
        }
        __syncthreads();

        // Accumulate over kernel window
        if (out_y < H_out && out_x < W_out) {
            // smem offset for this thread's output pixel
            // input coordinate = out_y*stride + ky*dil - pad = in_y0 + ty*stride_h + ky*dil_h
            // smem_y = ty*stride_h + ky*dil_h
            const int ic_local = ic - ic_start;  // weight index offset
            #pragma unroll
            for (int ky = 0; ky < kH; ky++) {
                #pragma unroll
                for (int kx = 0; kx < kW; kx++) {
                    int sy = ty * stride_h + ky * dil_h;
                    int sx = tx * stride_w + kx * dil_w;
                    float inp_val = smem[sy * smem_w + sx];
                    #pragma unroll
                    for (int i = 0; i < OC_TILE; i++) {
                        int oc = oc_start + i;
                        if (oc < OC) {
                            // weight: [OC, IC_per_group, kH, kW]
                            float w = __ldg(&weight[((oc * IC_per_group + ic_local) * kH + ky) * kW + kx]);
                            acc[i] += inp_val * w;
                        }
                    }
                }
            }
        }
        __syncthreads();
    }

    // Write output
    if (out_y < H_out && out_x < W_out) {
        #pragma unroll
        for (int i = 0; i < OC_TILE; i++) {
            int oc = oc_start + i;
            if (oc < OC) {
                float val = acc[i];
                if (bias != nullptr) val += __ldg(&bias[oc]);
                output[((n * OC + oc) * H_out + out_y) * W_out + out_x] = val;
            }
        }
    }
